import java.util.*;

class Solution {
    private Map<String, PriorityQueue<String>> flights = new HashMap<>();
    private LinkedList<String> trip = new LinkedList<>();

    public List<String> planTrip(String[][] tickets, String start) {
        for (String[] t : tickets)
            flights.computeIfAbsent(t[0], k -> new PriorityQueue<String>()).add(t[1]);
        dfs(start);
        return trip;
    }

    private void dfs(String a) {
        PriorityQueue<String> pq = flights.get(a);
        while (pq != null && !pq.isEmpty()) dfs(pq.poll()); // smallest unused ticket first
        trip.addFirst(a); // stuck here: this airport comes after everything explored from it
    }
}

