class Solution:
    def planTrip(self, tickets: List[List[str]], start: str) -> List[str]:
        g = defaultdict(list)
        for a, b in sorted(tickets, reverse=True): g[a].append(b)
        st = [start]; out = []
        while st:
            if g[st[-1]]: st.append(g[st[-1]].pop())
            else: out.append(st.pop())
        return out[::-1]

