function planTrip(tickets, start) {
  const g = new Map();
  for (const [a, b] of tickets) { if (!g.has(a)) g.set(a, []); g.get(a).push(b); }
  for (const l of g.values()) l.sort((x, y) => x < y ? 1 : x > y ? -1 : 0);
  const out = [];
  const visit = v => { const l = g.get(v) || []; while (l.length) visit(l.pop()); out.push(v); };
  visit(start); return out.reverse();
}
